def _parse_dt(value: str):
    # 2026-07-15T19:08:00+0330
    dt = datetime.strptime(value, '%Y-%m-%dT%H:%M:%S%z')
    return dt


def build_changelog_from_codebase(*, phone: str = '09357930033', replace_existing: bool = True):
    """
    ایجاد/بازنویسی changelog بر اساس تاریخ واقعی migrationها.
    created_by روی کاربر مالک محصول (قشقایی) تنظیم می‌شود.
    """
    user = User.objects.filter(phone=phone).first()
    if not user:
        raise ValueError(f'کاربر با شماره {phone} یافت نشد.')

    versions = [r['version'] for r in CODEBASE_RELEASES]
    if replace_existing:
        ProductRelease.objects.filter(version__in=versions).delete()

    created = 0
    updated = 0
    for rel in CODEBASE_RELEASES:
        released_at = _parse_dt(rel['released_at'])
        if timezone.is_naive(released_at):
            released_at = timezone.make_aware(released_at, timezone.get_current_timezone())

        obj, was_created = ProductRelease.objects.update_or_create(
            version=rel['version'],
            defaults={
                'title': rel['title'],
                'summary': rel['summary'],
                'released_at': released_at,
                'is_published': True,
                'created_by': user,
            },
        )
        obj.changes.all().delete()
        for order, (ctype, text) in enumerate(rel['changes'], start=1):
            ReleaseChange.objects.create(
                release=obj,
                change_type=ctype,
                text=text,
                sort_order=order,
            )
        if was_created:
            created += 1
        else:
            updated += 1

    return {
        'user_id': user.id,
        'username': user.username,
        'phone': user.phone,
        'created': created,
        'updated': updated,
        'total': ProductRelease.objects.filter(version__in=versions).count(),
    }
